// dialecto C++03 compartido
struct RenderType {
    enum Enum { Solid, MaterialPreview, Rendered, ZBuffer, Wireframe, NormalView, Alpha };
    Enum v;
    RenderType() : v(Solid) {}
    RenderType(Enum e) : v(e) {}
    operator Enum() const { return v; }
};

