bool UI2D_EsElemento2D(Object* o);
// la rot2d del elemento (NULL si no es un elemento 2D)
float* UI2D_Rot2dDe(Object* o);
// punteros al ancho/alto del elemento, si tiene rect propio (imagen/rectangulo):
